def record(item: tuple, lang: str) -> dict:
    offset = 1 if lang == "en" else 7
    return {
        "id": item[0],
        "question": item[offset],
        "options": item[offset + 1],
        "correct_answer": item[offset + 2],
        "category": item[offset + 3],
        "difficulty": "Hard",
        "bible_reference": item[offset + 4],
        "explanation": item[offset + 5],
    }


def main() -> None:
    for lang in ("en", "ne"):
        path = ROOT / "data" / f"questions_{lang}.json"
        records = json.loads(path.read_text(encoding="utf-8"))
        existing = {item["id"] for item in records}
        records.extend(record(item, lang) for item in QUESTIONS if item[0] not in existing)
        path.write_text(json.dumps(records, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print("Added 30 later-New-Testament hard questions.")


if __name__ == "__main__":
    main()
